insert into templates (country, visa_type, version, issued_on, source, general_notes) values ('MT', 'student_national_visa_over_90_days', '2.1', '2025-08-13', 'Identità, Central Visa Unit: Documentation required for Student National Visa (for visas of more than 90 days), version 2.1 dated 13.08.2025', '[{"en":"All documents must be submitted in English.","fr":"Tous les documents doivent être soumis en anglais."},{"en":"Documents that need translating must be translated by a translator on the authorised list of the Maltese authorities.","fr":"Les documents à traduire doivent être traduits par un traducteur figurant sur la liste officielle des autorités maltaises."}]'::jsonb)
insert into template_requirements (template_id, code, sort, kind, provider, title, help, mandatory, physical_default, conditions, review_points, pdf_ref) values
((select id from templates where country='MT' and visa_type='student_national_visa_over_90_days' and version='2.1'), '01', 10, 'document', 'student', '{"en":"Visa application form, signed","fr":"Formulaire de demande de visa, signé"}'::jsonb, '{"en":"Fully filled in and signed by the applicant.","fr":"Entièrement rempli et signé par le demandeur."}'::jsonb, true, true, '[]'::jsonb, '[]'::jsonb, '01'),
((select id from templates where country='MT' and visa_type='student_national_visa_over_90_days' and version='2.1'), '02', 20, 'document', 'student', '{"en":"Passport","fr":"Passeport"}'::jsonb, '{"en":"The passport must be valid for at least 10 months.","fr":"Le passeport doit être valable au moins 10 mois."}'::jsonb, true, true, '[]'::jsonb, '[{"en":"Validity of at least 10 months","fr":"Validité d’au moins 10 mois"}]'::jsonb, '02'),
((select id from templates where country='MT' and visa_type='student_national_visa_over_90_days' and version='2.1'), '03', 30, 'document', 'student', '{"en":"Passport photo","fr":"Photo d’identité"}'::jsonb, '{"en":"One photo that meets ICAO standards.","fr":"Une photo conforme aux normes OACI."}'::jsonb, true, true, '[]'::jsonb, '[]'::jsonb, '03'),
((select id from templates where country='MT' and visa_type='student_national_visa_over_90_days' and version='2.1'), '04', 40, 'document', 'agent', '{"en":"VFS appointment letter","fr":"Lettre de rendez-vous VFS"}'::jsonb, '{"en":"The application must be submitted at least 9 weeks before the course starts.","fr":"La demande doit être déposée au moins 9 semaines avant le début du cours."}'::jsonb, true, true, '[]'::jsonb, '[]'::jsonb, '04'),
((select id from templates where country='MT' and visa_type='student_national_visa_over_90_days' and version='2.1'), '05', 50, 'document', 'student', '{"en":"School enrolment letter","fr":"Lettre d’inscription de l’établissement"}'::jsonb, '{"en":"The letter must state the details below clearly.","fr":"La lettre doit indiquer clairement les informations ci-dessous."}'::jsonb, true, false, '[]'::jsonb, '[{"en":"Institution name, as registered with MFHEA","fr":"Nom de l’établissement, tel qu’enregistré auprès du MFHEA"},{"en":"Full course name, as listed on the MFHEA website","fr":"Nom complet du cours, tel que publié sur le site du MFHEA"},{"en":"MQF level","fr":"Niveau MQF"},{"en":"Number of ECTS","fr":"Nombre d’ECTS"},{"en":"Duration in months covered by the letter, and type (full time or part time)","fr":"Durée en mois couverte par la lettre, et type (temps plein ou temps partiel)"},{"en":"Course hiatus periods, such as Easter and summer holidays","fr":"Périodes d’interruption, comme les vacances de Pâques et d’été"},{"en":"Course hours per week, specifying contact hours","fr":"Heures de cours par semaine, avec les heures de contact précisées"},{"en":"Address where the student will attend lectures","fr":"Adresse où l’étudiant suivra les cours"}]'::jsonb, '05'),
((select id from templates where country='MT' and visa_type='student_national_visa_over_90_days' and version='2.1'), '05-payment', 51, 'document', 'student', '{"en":"Proof of payment","fr":"Preuve de paiement"}'::jsonb, '{"en":"A receipt or an invoice.","fr":"Un reçu ou une facture."}'::jsonb, true, false, '[]'::jsonb, '[]'::jsonb, '05'),
((select id from templates where country='MT' and visa_type='student_national_visa_over_90_days' and version='2.1'), '06', 60, 'document', 'student', '{"en":"Bank statements, last 3 months","fr":"Relevés bancaires des 3 derniers mois"}'::jsonb, '{"en":"The funds must be at least 75% of the national minimum wage for every month of study.","fr":"Les fonds doivent représenter au moins 75 % du salaire minimum national pour chaque mois d’études."}'::jsonb, true, false, '[]'::jsonb, '[{"en":"Covers the last 3 months","fr":"Couvre les 3 derniers mois"},{"en":"Funds of at least 75% of the national minimum wage for every month of study","fr":"Fonds d’au moins 75 % du salaire minimum national pour chaque mois d’études"}]'::jsonb, '06'),
((select id from templates where country='MT' and visa_type='student_national_visa_over_90_days' and version='2.1'), '06-certificate', 61, 'document', 'student', '{"en":"Recent bank certificate","fr":"Attestation bancaire récente"}'::jsonb, '{"en":"It must show adequate funds to support the stay in Malta.","fr":"Elle doit montrer des fonds suffisants pour le séjour à Malte."}'::jsonb, true, false, '[]'::jsonb, '[]'::jsonb, '06'),
