((select id from templates where country='MT' and visa_type='student_national_visa_over_90_days' and version='2.1'), '06-sponsor-declaration', 63, 'document', 'student', '{"en":"Sponsor’s declaration letter, signed","fr":"Lettre de déclaration du garant, signée"}'::jsonb, '{"en":"","fr":""}'::jsonb, true, true, '[{"field":"funding","op":"eq","value":"sponsored"}]'::jsonb, '[]'::jsonb, '06 ii'),
((select id from templates where country='MT' and visa_type='student_national_visa_over_90_days' and version='2.1'), '06-sponsor-id', 64, 'document', 'student', '{"en":"Sponsor’s ID card or passport","fr":"Pièce d’identité ou passeport du garant"}'::jsonb, '{"en":"ID card front and back, or the passport page with the photo. Both sides can be in one file.","fr":"Pièce d’identité recto et verso, ou page du passeport avec la photo. Les deux faces peuvent être dans un seul fichier."}'::jsonb, true, false, '[{"field":"funding","op":"eq","value":"sponsored"}]'::jsonb, '[]'::jsonb, '06 iii'),
((select id from templates where country='MT' and visa_type='student_national_visa_over_90_days' and version='2.1'), '07', 70, 'document', 'student', '{"en":"International bank card, front and back","fr":"Carte bancaire internationale, recto et verso"}'::jsonb, '{"en":"The card the student will use to access funds in Malta. Both sides can be in one file.","fr":"La carte que l’étudiant utilisera pour accéder à ses fonds à Malte. Les deux faces peuvent être dans un seul fichier."}'::jsonb, true, false, '[]'::jsonb, '[]'::jsonb, '07'),
((select id from templates where country='MT' and visa_type='student_national_visa_over_90_days' and version='2.1'), '08-mqf5', 80, 'document', 'student', '{"en":"Medical and travel insurance","fr":"Assurance maladie et voyage"}'::jsonb, '{"en":"For students on MQF level 5 and over who can apply for a study residence permit once in Malta.","fr":"Pour les étudiants de niveau MQF 5 et plus pouvant demander un permis de résidence pour études une fois à Malte."}'::jsonb, true, false, '[{"field":"mqfLevel","op":"gte","value":5}]'::jsonb, '[{"en":"Valid for the Schengen area","fr":"Valable dans l''espace Schengen"},{"en":"Minimum medical coverage of €30,000","fr":"Couverture médicale minimale de 30 000 €"},{"en":"Covers at least 91 consecutive days from the first point of entry in the Schengen area","fr":"Couvre au moins 91 jours consécutifs à partir de la première entrée dans l’espace Schengen"},{"en":"Valid for study purpose","fr":"Valable pour des études"}]'::jsonb, '08'),
((select id from templates where country='MT' and visa_type='student_national_visa_over_90_days' and version='2.1'), '08-mqf4', 81, 'document', 'student', '{"en":"Medical and travel insurance","fr":"Assurance maladie et voyage"}'::jsonb, '{"en":"For students on MQF level 4 and under.","fr":"Pour les étudiants de niveau MQF 4 et moins."}'::jsonb, true, false, '[{"field":"mqfLevel","op":"lt","value":5}]'::jsonb, '[{"en":"Valid for the Schengen area","fr":"Valable dans l''espace Schengen"},{"en":"Minimum medical coverage of €30,000","fr":"Couverture médicale minimale de 30 000 €"},{"en":"Valid for the whole stay, from the first point of entry in the Schengen area until exit","fr":"Valable pendant tout le séjour, de la première entrée dans l’espace Schengen jusqu’à la sortie"},{"en":"Valid for study purpose","fr":"Valable pour des études"}]'::jsonb, '08'),
((select id from templates where country='MT' and visa_type='student_national_visa_over_90_days' and version='2.1'), '08-benefits', 82, 'document', 'student', '{"en":"Table of benefits","fr":"Tableau des garanties"}'::jsonb, '{"en":"Only needed if the certificate of insurance does not show the details above.","fr":"Nécessaire uniquement si le certificat d’assurance n’indique pas les informations ci-dessus."}'::jsonb, false, false, '[{"field":"mqfLevel","op":"gte","value":1}]'::jsonb, '[]'::jsonb, '08'),
((select id from templates where country='MT' and visa_type='student_national_visa_over_90_days' and version='2.1'), '09', 90, 'document', 'student', '{"en":"Flight itinerary to Malta","fr":"Itinéraire de vol vers Malte"}'::jsonb, '{"en":"The full itinerary with the student’s name, the date of the flight and all stops. Arrival must be no more than two weeks before the course starts.","fr":"L’itinéraire complet avec le nom de l’étudiant, la date du vol et toutes les escales. L’arrivée ne doit pas avoir lieu plus de deux semaines avant le début du cours."}'::jsonb, true, false, '[]'::jsonb, '[{"en":"Student’s name, date of flight and all stops shown","fr":"Nom de l’étudiant, date du vol et toutes les escales indiqués"},{"en":"Entry no more than two weeks before the course starts","fr":"Entrée au plus deux semaines avant le début du cours"}]'::jsonb, '09'),
((select id from templates where country='MT' and visa_type='student_national_visa_over_90_days' and version='2.1'), '09-return', 91, 'document', 'student', '{"en":"Return ticket","fr":"Billet de retour"}'::jsonb, '{"en":"Required because the course is shorter than six months. The ticket must be for after the course ends.","fr":"Obligatoire car le cours dure moins de six mois. Le billet doit être postérieur à la fin du cours."}'::jsonb, true, false, '[{"field":"courseMonths","op":"lt","value":6}]'::jsonb, '[]'::jsonb, '09'),
((select id from templates where country='MT' and visa_type='student_national_visa_over_90_days' and version='2.1'), '10-school', 100, 'document', 'student', '{"en":"Accommodation letter from the school","fr":"Lettre d’hébergement de l’établissement"}'::jsonb, '{"en":"On the school’s letterhead, signed and stamped. It must state name, surname, passport number, address and duration of accommodation.","fr":"Sur papier à en-tête de l’établissement, signée et tamponnée. Elle doit indiquer nom, prénom, numéro de passeport, adresse et durée de l’hébergement."}'::jsonb, true, true, '[{"field":"accommodation","op":"eq","value":"school"}]'::jsonb, '[{"en":"In the applicant’s name, covering the first 14 nights","fr":"Au nom du demandeur, couvrant les 14 premières nuits"}]'::jsonb, '10 a'),
((select id from templates where country='MT' and visa_type='student_national_visa_over_90_days' and version='2.1'), '10-lease', 101, 'document', 'student', '{"en":"Registered lease agreement","fr":"Contrat de location enregistré"}'::jsonb, '{"en":"Signed by both parties. It must state the duration, home address, the applicant’s name and the rent.","fr":"Signé par les deux parties. Il doit indiquer la durée, l’adresse, le nom du demandeur et le loyer."}'::jsonb, true, true, '[{"field":"accommodation","op":"eq","value":"lease"}]'::jsonb, '[{"en":"In the applicant’s name, covering the first 14 nights","fr":"Au nom du demandeur, couvrant les 14 premières nuits"}]'::jsonb, '10 b'),
((select id from templates where country='MT' and visa_type='student_national_visa_over_90_days' and version='2.1'), '10-host-declaration', 102, 'document', 'student', '{"en":"Host’s declaration","fr":"Déclaration de l’hébergeant"}'::jsonb, '{"en":"Signed and stamped by a local lawyer or notary.","fr":"Signée et tamponnée par un avocat ou un notaire local."}'::jsonb, true, true, '[{"field":"accommodation","op":"eq","value":"host"}]'::jsonb, '[]'::jsonb, '10 c i'),
((select id from templates where country='MT' and visa_type='student_national_visa_over_90_days' and version='2.1'), '10-host-id', 103, 'document', 'student', '{"en":"Host’s identity card","fr":"Pièce d’identité de l’hébergeant"}'::jsonb, '{"en":"A copy of the host’s identity card.","fr":"Une copie de la pièce d’identité de l’hébergeant."}'::jsonb, true, false, '[{"field":"accommodation","op":"eq","value":"host"}]'::jsonb, '[]'::jsonb, '10 c ii'),
((select id from templates where country='MT' and visa_type='student_national_visa_over_90_days' and version='2.1'), '10-host-residence', 104, 'document', 'student', '{"en":"Proof of the host’s link to the residence","fr":"Preuve du lien de l’hébergeant avec le logement"}'::jsonb, '{"en":"Needed when the applicant stays at a secondary address. A contract of sale, lease agreement or utility bill.","fr":"Nécessaire si le demandeur est hébergé à une adresse secondaire. Un contrat de vente, un contrat de location ou une facture de services."}'::jsonb, true, false, '[{"field":"accommodation","op":"eq","value":"host"},{"field":"hostSecondaryAddress","op":"truthy"}]'::jsonb, '[]'::jsonb, '10 c iii'),
((select id from templates where country='MT' and visa_type='student_national_visa_over_90_days' and version='2.1'), '10-hotel', 105, 'document', 'student', '{"en":"Hotel or short-term rental booking","fr":"Réservation d’hôtel ou de location de courte durée"}'::jsonb, '{"en":"A booking of at least 14 consecutive nights from the planned arrival date in Malta.","fr":"Une réservation d’au moins 14 nuits consécutives à partir de la date d’arrivée prévue à Malte."}'::jsonb, true, false, '[{"field":"accommodation","op":"eq","value":"hotel"}]'::jsonb, '[{"en":"In the applicant’s name, at least 14 consecutive nights","fr":"Au nom du demandeur, au moins 14 nuits consécutives"}]'::jsonb, '10 d'),
